 1	import React, { useState } from 'react';
 2	import { Box, Button } from '@mui/material';
 3	import { styled } from '@mui/material/styles';
 4	
 5	// 导入布局组件
 6	import SidebarContainer from './components/SidebarContainer';
 7	import BuilderHeader from './components/BuilderHeader';
 8	// 不再使用ContentContainer，直接使用Box组件
 9	
 10	// 导入步骤组件
 11	import BasicInfoStep from './components/BasicInfoStep';
 12	import SystemPromptStep from './components/SystemPromptStep';
 13	import FeaturesStep from './components/FeaturesStep';
 14	import ToolOrchestrationStep from './components/ToolOrchestrationStep';
 15	
 16	// 导入类型
 17	import { Tool, KnowledgeBase, AgentConfig } from './components/types';
 18	import { defaultExtensionConfig } from './components/extensionConfig';
 19	
 20	// 工具编排项接口
 21	interface OrchestrationItem {
 22	 id: string;
 23	 type: 'tool' | 'knowledgeBase' | 'extension';
 24	 name: string;
 25	 description: string;
 26	 config?: Record<string, unknown>;
 27	 enabled: boolean;
 28	 order: number;
 29	}
 30	
 31	// 高级设置接口
 32	export interface AdvancedSettings {
 33	 temperature: number;
 34	 maxTokens: number;
 35	 topP: number;
 36	 frequencyPenalty: number;
 37	 presencePenalty: number;
 38	 contextCompression: boolean;
 39	}
 40	
 41	// 生成默认高级设置
 42	const defaultAdvancedSettings: AdvancedSettings = {
 43	 temperature: 0.7,
 44	 maxTokens: 2048,
 45	 topP: 1,
 46	 frequencyPenalty: 0,
 47	 presencePenalty: 0,
 48	 contextCompression: false
 49	};
 50	
 51	// 定义磨砂背景容器
 52	const GlassmorphismBackground = styled(Box)(({ theme }) => ({
 53	 position: 'fixed', // 修改为fixed定位，覆盖整个视口
 54	 top: 0,
 55	 left: 0,
 56	 right: 0,
 57	 bottom: 0,
 58	 width: '100%',
 59	 height: '100%',
 60	 zIndex: -1, // 改为-1，确保完全在内容下层且不影响用户交互
 61	 background: `linear-gradient(135deg, ${theme.palette.primary.light}30, ${theme.palette.secondary.light}40, ${theme.palette.info.light}30)`,
 62	 pointerEvents: 'none', // 不拦截任何鼠标事件
 63	 '&:before': {
 64	 content: '""',
 65	 position: 'absolute',
 66	 top: 0,
 67	 right: 0,
 68	 width: '400px',
 69	 height: '400px',
 70	 background: `radial-gradient(circle, ${theme.palette.primary.main}30 0%, transparent 70%)`,
 71	 borderRadius: '50%',
 72	 transform: 'translate(20%, -20%)',
 73	 filter: 'blur(40px)',
 74	 pointerEvents: 'none'
 75	 },
 76	 '&:after': {
 77	 content: '""',
 78	 position: 'absolute',
 79	 bottom: 0,
 80	 left: 0,
 81	 width: '500px',
 82	 height: '500px',
 83	 background: `radial-gradient(circle, ${theme.palette.secondary.main}30 0%, transparent 70%)`,
 84	 borderRadius: '50%',
 85	 transform: 'translate(-20%, 20%)',
 86	 filter: 'blur(40px)',
 87	 pointerEvents: 'none'
 88	 }
 89	}));
 90	
 91	// 内容容器组件
 92	const ContentWrapper = styled(Box)(() => ({
 93	 position: 'relative',
 94	 zIndex: 1,
 95	 minHeight: '100vh',
 96	 display: 'flex',
 97	 flexDirection: 'column',
 98	 overflow: 'hidden'
 99	}));
 100	
 101	const AgentBuilder: React.FC = () => {
 102	 // 当前未使用导航功能，但将来可能添加返回按钮等功能
 103	 // const navigate = useNavigate();
 104	 // const { state } = useAppContext();
 105	 
 106	 // 活动步骤状态
 107	 const [activeStep, setActiveStep] = useState(0);
 108	 
 109	 // 已完成步骤的状态
 110	 const [completed, setCompleted] = useState<{[k: number]: boolean}>({});
 111	 
 112	 // 功能配置子标签页状态
 113	 const [featureTabValue, setFeatureTabValue] = useState(0);
 114	 
 115	 // 扩展工具配置状态
 116	 const [extensionToolsConfig, setExtensionToolsConfig] = useState(defaultExtensionConfig);
 117	 
 118	 // 工具编排状态
 119	 const [orchestrationItems, setOrchestrationItems] = useState<OrchestrationItem[]>([]);
 120	 
 121	 // 智能体配置状态
 122	 const [agentConfig, setAgentConfig] = useState<AgentConfig>({
 123	 name: '',
 124	 description: '',
 125	 systemPrompt: '你是一个由向量数据库支持的智能助手，拥有以下能力：\n1. 可以回答用户关于向量数据库的问题\n2. 可以进行代码解释和分析\n3. 可以连接网络搜索和获取最新信息\n4. 可以处理各种文档和数据',
 126	 selectedTools: [],
 127	 selectedKnowledgeBases: [],
 128	 agentType: 'chat',
 129	 icon: 'robot',
 130	 tags: [],
 131	 language: 'zh-CN',
 132	 isPublic: false,
 133	 advanced: defaultAdvancedSettings
 134	 });
 135	 
 136	 // 处理名称变更
 137	 const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
 138	 setAgentConfig({
 139	 ...agentConfig,
 140	 name: event.target.value
 141	 });
 142	 };
 143	 
 144	 // 处理描述变更
 145	 const handleDescriptionChange = (event: React.ChangeEvent<HTMLInputElement>) => {
 146	 setAgentConfig({
 147	 ...agentConfig,
 148	 description: event.target.value
 149	 });
 150	 };
 151	 
 152	 // 处理智能体类型变更
 153	 const handleAgentTypeChange = (value: string) => {
 154	 setAgentConfig({
 155	 ...agentConfig,
 156	 agentType: value
 157	 });
 158	 };
 159	 
 160	 // 处理图标变更
 161	 const handleIconChange = (icon: string) => {
 162	 setAgentConfig({
 163	 ...agentConfig,
 164	 icon: icon
 165	 });
 166	 };
 167	 
 168	 // 处理标签变更
 169	 const handleTagsChange = (tags: string[]) => {
 170	 setAgentConfig({
 171	 ...agentConfig,
 172	 tags: tags
 173	 });
 174	 };
 175	 
 176	 // 处理语言变更
 177	 const handleLanguageChange = (language: string) => {
 178	 setAgentConfig({
 179	 ...agentConfig,
 180	 language: language
 181	 });
 182	 };
 183	 
 184	 // 处理可见性变更
 185	 const handleVisibilityChange = (isPublic: boolean) => {
 186	 setAgentConfig({
 187	 ...agentConfig,
 188	 isPublic: isPublic
 189	 });
 190	 };
 191	 
 192	 // 处理系统提示词变更
 193	 const handleSystemPromptChange = (value: string) => {
 194	 setAgentConfig({
 195	 ...agentConfig,
 196	 systemPrompt: value
 197	 });
 198	 };
 199	 
 200	 // 重置系统提示词
 201	 const handleResetSystemPrompt = () => {
 202	 setAgentConfig({
 203	 ...agentConfig,
 204	 systemPrompt: '你是一个由向量数据库支持的智能助手，拥有以下能力：\n1. 可以回答用户关于向量数据库的问题\n2. 可以进行代码解释和分析\n3. 可以连接网络搜索和获取最新信息\n4. 可以处理各种文档和数据'
 205	 });
 206	 };
 207	 
 208	 // 工具选择切换
 209	 const toggleToolSelection = (tool: Tool) => {
 210	 const selectedTools = [...agentConfig.selectedTools];
 211	 const index = selectedTools.findIndex(t => t.id === tool.id);
 212	 
 213	 if (index > -1) {
 214	 // 如果工具已选中，则移除
 215	 selectedTools.splice(index, 1);
 216	 } else {
 217	 // 否则添加到选中列表
 218	 selectedTools.push(tool);
 219	 }
 220	 
 221	 setAgentConfig({
 222	 ...agentConfig,
 223	 selectedTools
 224	 });
 225	 };
 226	 
 227	 // 知识库选择切换
 228	 const toggleKnowledgeBaseSelection = (kb: KnowledgeBase) => {
 229	 const selectedKBs = [...agentConfig.selectedKnowledgeBases];
 230	 const index = selectedKBs.findIndex(k => k.id === kb.id);
 231	 
 232	 if (index > -1) {
 233	 // 如果知识库已选中，则移除
 234	 selectedKBs.splice(index, 1);
 235	 } else {
 236	 // 否则添加到选中列表
 237	 selectedKBs.push(kb);
 238	 }
 239	 
 240	 setAgentConfig({
 241	 ...agentConfig,
 242	 selectedKnowledgeBases: selectedKBs
 243	 });
 244	 };
 245	 
 246	 // 处理扩展工具配置变更
 247	 const handleExtensionToolsConfigChange = (config: typeof defaultExtensionConfig) => {
 248	 setExtensionToolsConfig(config);
 249	 };
 250	
 251	 // 处理工具编排变更
 252	 const handleOrchestrationItemsChange = React.useCallback((items: OrchestrationItem[]) => {
 253	 setOrchestrationItems(items);
 254	 }, []);
 255	 
 256	 // 检查步骤是否已完成
 257	 const isStepComplete = (step: number) => {
 258	 return !!completed[step];
 259	 };
 260	 
 261	 // 切换步骤
 262	 const handleStepChange = (step: number) => {
 263	 setActiveStep(step);
 264	 };
 265	 
 266	 // 下一步
 267	 const handleNext = () => {
 268	 const newCompleted = { ...completed };
 269	 // 标记当前步骤为已完成
 270	 newCompleted[activeStep] = true;
 271	 setCompleted(newCompleted);
 272	 
 273	 // 移动到下一步
 274	 setActiveStep((prevActiveStep) => prevActiveStep + 1);
 275	 };
 276	 
 277	 // 上一步
 278	 const handleBack = () => {
 279	 setActiveStep((prevActiveStep) => prevActiveStep - 1);
 280	 };
 281	 
 282	 // 完成步骤
 283	 const completeStep = () => {
 284	 const newCompleted = { ...completed };
 285	 newCompleted[activeStep] = true;
 286	 setCompleted(newCompleted);
 287	 };
 288	
 289	 // 最终完成创建智能体
 290	 const handleFinalComplete = () => {
 291	 completeStep();
 292	 // 添加工具编排配置到智能体配置中
 293	 const finalConfig = {
 294	 ...agentConfig,
 295	 extensionTools: extensionToolsConfig,
 296	 orchestration: orchestrationItems
 297	 };
 298	 
 299	 console.log('最终智能体配置:', finalConfig);
 300	 // TODO: 调用 API 保存智能体配置
 301	 
 302	 // 可以导航到成功页面或返回列表
 303	 // navigate('/agent-list');
 304	 };
 305	 
 306	 // 保存智能体
 307	 const handleSave = () => {
 308	 console.log('保存智能体配置:', agentConfig);
 309	 // TODO: 调用 API 保存智能体配置
 310	 
 311	 // 导航回列表页
 312	 // navigate('/agent-list');
 313	 };
 314	 
 315	 // 检查是否可以继续（是否满足最低要求）
 316	 const canContinue = (step: number) => {
 317	 switch(step) {
 318	 case 0:
 319	 return agentConfig.name.trim() !== '';
 320	 case 1:
 321	 return agentConfig.systemPrompt.trim() !== '';
 322	 case 2:
 323	 return true; // 没有特定要求
 324	 case 3:
 325	 return true; // 工具编排是可选的
 326	 default:
 327	 return false;
 328	 }
 329	 };
 330	 
 331	 // 渲染工具选择芯片
 332	 const renderToolChips = () => {
 333	 // 这里可以渲染工具芯片组件
 334	 return null;
 335	 };
 336	 
 337	 // 检查是否可以保存（基本必填项是否已填）
 338	 const canSave = agentConfig.name.trim() !== '' && agentConfig.systemPrompt.trim() !== '';
 339	 
 340	 // 步骤标题
 341	 const stepTitles = ['基本信息设置', '系统提示词设置', '功能配置', '工具编排'];
 342	 
 343	 // 步骤配置
 344	 const steps = [
 345	 {
 346	 id: 0,
 347	 title: '基本信息',
 348	 isRequired: true,
 349	 isComplete: agentConfig.name.trim() !== '',
 350	 status: agentConfig.name ? '已填写' : '必填'
 351	 },
 352	 {
 353	 id: 1,
 354	 title: '系统提示词',
 355	 isRequired: true,
 356	 isComplete: agentConfig.systemPrompt.trim() !== '',
 357	 status: agentConfig.systemPrompt ? '已填写' : '必填'
 358	 },
 359	 {
 360	 id: 2,
 361	 title: '功能配置',
 362	 isRequired: false,
 363	 isComplete: isStepComplete(2),
 364	 isOptional: true,
 365	 status: '可选'
 366	 },
 367	 {
 368	 id: 3,
 369	 title: '工具编排',
 370	 isRequired: false,
 371	 isComplete: isStepComplete(3),
 372	 isOptional: true,
 373	 status: '可选'
 374	 }
 375	 ];
 376	 
 377	 return (
 378	 <>
 379	 {/* 固定底层背景 */}
 380	 <GlassmorphismBackground />
 381	 
 382	 {/* 内容容器 */}
 383	 <ContentWrapper>
 384	 {/* 顶部灵动岛 */}
 385	 <BuilderHeader
 386	 title="创建智能体"
 387	 agentName={agentConfig.name}
 388	 pageName="智能体管理"
 389	 canSave={canSave}
 390	 onSave={handleSave}
 391	 currentStep={activeStep}
 392	 totalSteps={stepTitles.length}
 393	 isMainHeader={true}
 394	 />
 395	 <Box sx={{ 
 396	 display: 'flex', 
 397	 flexGrow: 1,
 398	 background: 'rgba(255, 255, 255, 0.65)',
 399	 backdropFilter: 'blur(8px)',
 400	 WebkitBackdropFilter: 'blur(8px)',
 401	 borderRadius: '16px',
 402	 margin: 2,
 403	 marginTop: 4, // 增加与顶部灵动岛的间距
 404	 marginBottom: 3,
 405	 border: '1px solid rgba(255, 255, 255, 0.3)',
 406	 boxShadow: '0 8px 32px rgba(0, 0, 0, 0.05)',
 407	 height: 'calc(100vh - 160px)', // 调整高度，留出更多空间给顶部灵动岛
 408	 overflow: 'auto',
 409	 position: 'relative',
 410	 zIndex: 2
 411	 }}
 412	 data-agent-builder-main>
 413	 {/* 左侧步骤导航 */}
 414	 <SidebarContainer
 415	 agentName={agentConfig.name}
 416	 activeStep={activeStep}
 417	 steps={steps}
 418	 onStepChange={handleStepChange}
 419	 onSave={handleSave}
 420	 canSave={canSave}
 421	 collapsed={false /* 内容区步骤栏始终展开，不跟随全局导航折叠 */}
 422	 />
 423	 
 424	 {/* 右侧内容区域 - 直接显示内容，不使用ContentContainer */}
 425	 <Box sx={{ flex: 1, p: 2, overflow: 'auto' }}>
 426	 {/* 基本信息页 */}
 427	 {activeStep === 0 && (
 428	 <BasicInfoStep
 429	 name={agentConfig.name}
 430	 description={agentConfig.description}
 431	 onNameChange={handleNameChange}
 432	 onDescriptionChange={handleDescriptionChange}
 433	 // 新增属性
 434	 agentType={agentConfig.agentType}
 435	 onAgentTypeChange={handleAgentTypeChange}
 436	 icon={agentConfig.icon}
 437	 onIconChange={handleIconChange}
 438	 tags={agentConfig.tags}
 439	 onTagsChange={handleTagsChange}
 440	 language={agentConfig.language}
 441	 onLanguageChange={handleLanguageChange}
 442	 isPublic={agentConfig.isPublic}
 443	 onVisibilityChange={handleVisibilityChange}
 444	 />
 445	 )}
 446	 
 447	 {/* 系统提示词页 */}
 448	 {activeStep === 1 && (
 449	 <SystemPromptStep
 450	 value={agentConfig.systemPrompt}
 451	 onChange={handleSystemPromptChange}
 452	 onReset={handleResetSystemPrompt}
 453	 />
 454	 )}
 455	 
 456	 {/* 功能配置页 */}
 457	 {activeStep === 2 && (
 458	 <>
 459	 <FeaturesStep
 460	 tabValue={featureTabValue}
 461	 onTabChange={setFeatureTabValue}
 462	 selectedTools={agentConfig.selectedTools}
 463	 toggleToolSelection={toggleToolSelection}
 464	 renderToolChips={renderToolChips}
 465	 selectedKnowledgeBases={agentConfig.selectedKnowledgeBases}
 466	 toggleKnowledgeBaseSelection={toggleKnowledgeBaseSelection}
 467	 extensionToolsConfig={extensionToolsConfig}
 468	 onExtensionToolsConfigChange={handleExtensionToolsConfigChange}
 469	 onBack={handleBack}
 470	 onComplete={handleNext}
 471	 canContinue={canContinue(activeStep)}
 472	 />
 473	 </>
 474	 )}
 475	 
 476	 {/* 工具编排页 */}
 477	 {activeStep === 3 && (
 478	 <ToolOrchestrationStep
 479	 selectedTools={agentConfig.selectedTools}
 480	 selectedKnowledgeBases={agentConfig.selectedKnowledgeBases}
 481	 extensionToolsConfig={extensionToolsConfig}
 482	 orchestrationItems={orchestrationItems}
 483	 onOrchestrationItemsChange={handleOrchestrationItemsChange}
 484	 onBack={handleBack}
 485	 onComplete={handleFinalComplete}
 486	 canContinue={canContinue(activeStep)}
 487	 />
 488	 )}
 489	 
 490	 {/* 底部导航按钮 - 仅在第一步显示 */}
 491	 {activeStep === 0 && (
 492	 <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 3 }}>
 493	 <Button 
 494	 onClick={handleNext} 
 495	 variant="contained" 
 496	 color="primary" 
 497	 size="small"
 498	 disabled={!canContinue(activeStep)}
 499	 >
 500	 下一步
 501	 </Button>
 502	 </Box>
 503	 )}
 504	 
 505	 {/* 第二步导航按钮 */}
 506	 {activeStep === 1 && (
 507	 <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 3 }}>
 508	 <Button onClick={handleBack} variant="outlined" size="small">
 509	 上一步
 510	 </Button>
 511	 <Button 
 512	 onClick={handleNext} 
 513	 variant="contained" 
 514	 color="primary" 
 515	 size="small"
 516	 disabled={!canContinue(activeStep)}
 517	 >
 518	 下一步
 519	 </Button>
 520	 </Box>
 521	 )}
 522	 </Box>
 523	 </Box>
 524	 </ContentWrapper>
 525	 </>
 526	 );
 527	};
 528	
 529	export default AgentBuilder;
