 26	// 工具类别 - 扩展为更多实际的工具类别
 27	export enum ToolCategory {
 28	 SEARCH = 'search', // 搜索工具
 29	 RETRIEVAL = 'retrieval', // 检索工具 
 30	 REASONING = 'reasoning', // 推理工具
 31	 MULTIMODAL = 'multimodal', // 多模态工具
 32	 INTEGRATION = 'integration', // 集成工具
 33	 KNOWLEDGE = 'knowledge', // 知识处理工具
 34	 WEB = 'web', // 网页工具
 35	 DEVELOPMENT = 'development', // 开发工具
 36	 DOCUMENT = 'document', // 文档工具
 37	 MULTIMEDIA = 'multimedia' // 多媒体工具
 38	}
 39	
 40	// 知识库检索配置接口
 41	export interface KnowledgeBaseRetrievalConfig {
 42	 // 检索策略
 43	 strategy: 'vector' | 'keyword' | 'hybrid'; // 向量检索、关键词检索、混合检索
 44	 
 45	 // 向量检索参数
 46	 vectorParams: {
 47	 topK: number; // 返回结果数量，默认5
 48	 scoreThreshold: number; // 相似度阈值，默认0.7
 49	 includeMetadata: boolean; // 是否包含元数据
 50	 };
 51	 
 52	 // 关键词检索参数
 53	 keywordParams: {
 54	 topK: number; // 返回结果数量，默认3
 55	 boost: number; // 权重提升，默认1.0
 56	 };
 57	 
 58	 // RRF (Reciprocal Rank Fusion) 参数
 59	 rrfParams: {
 60	 enabled: boolean; // 是否启用RRF
 61	 k: number; // RRF参数k值，默认60
 62	 vectorWeight: number; // 向量检索权重，默认0.6
 63	 keywordWeight: number; // 关键词检索权重，默认0.4
 64	 };
 65	 
 66	 // 索引配置
 67	 indexConfig: {
 68	 type: 'IVF_PQ' | 'HNSW' | 'IVF_FLAT' | 'FLAT'; // 索引类型
 69	 dimension: number; // 向量维度
 70	 metric: 'cosine' | 'euclidean' | 'dot_product'; // 距离度量
 71	 // IVF_PQ 特有参数
 72	 ivfPqParams?: {
 73	 nlist: number; // 聚类中心数量，默认100
 74	 nprobe: number; // 搜索的聚类数量，默认10
 75	 m: number; // PQ编码的子向量数量，默认8
 76	 nbits: number; // 每个子向量的bit数，默认8
 77	 };
 78	 // HNSW 特有参数
 79	 hnswParams?: {
 80	 M: number; // 每个节点的最大连接数，默认16
 81	 efConstruction: number; // 构建时的动态列表大小，默认200
 82	 efSearch: number; // 搜索时的动态列表大小，默认64
 83	 };
 84	 };
 85	}
