 43	
 44	// 缓存选项接口
 45	interface CacheOptions {
 46	 ttl?: number; // 缓存生存时间（毫秒）
 47	 methods?: string[]; // 需要缓存的HTTP方法
 48	 keyGenerator?: (req: Request) => string; // 缓存键生成器
 49	}
 50	
 51	// 创建缓存实例
 52	const cache = new MemoryCache();
 53	cache.startCleanup(60 * 1000); // 每分钟清理一次
 54	
 55	// 缓存中间件
 56	export const cacheMiddleware = (options: CacheOptions = {}) => {
 57	 const {
 58	 ttl = 5 * 60 * 1000, // 默认5分钟
 59	 methods = ['GET'], // 默认只缓存GET请求
 60	 keyGenerator = (req) => `${req.method}:${req.originalUrl}` // 默认使用方法+URL作为键
 61	 } = options;
 62	 
 63	 return (req: Request, res: Response, next: NextFunction) => {
 64	 // 只缓存指定的HTTP方法
 65	 if (!methods.includes(req.method)) {
 66	 return next();
 67	 }
 68	 
 69	 // 生成缓存键
 70	 const key = keyGenerator(req);
 71	 
 72	 // 检查缓存
 73	 const cachedData = cache.get(key);
 74	 if (cachedData) {
 75	 logger.debug(`缓存命中: ${key}`);
 76	 return res.json(cachedData);
 77	 }
 78	 
 79	 // 保存原始的JSON方法
 80	 const originalJson = res.json;
 81	 
 82	 // 重写JSON方法以拦截响应
 83	 res.json = function(data) {
 84	 logger.debug(`缓存数据: ${key}`);
 85	 cache.set(key, data, ttl);
 86	 
 87	 // 恢复原始JSON方法的行为
 88	 return originalJson.call(this, data);
 89	 };
 90	 
 91	 next();
 92	 };
 93	};
