","workspace_file_chunks":[]},{"status":"success","request_id":"64682dd5-5cf5-4ac3-9fcd-619d79ad42ef","request_message":"","structured_output_nodes":[{"id":1,"type":5,"content":"","tool_use":{"tool_use_id":"toolu_01652EZuDyHXK547Pkx5K4su","tool_name":"save-file","input_json":"{"instructions_reminder": "LIMIT THE FILE CONTENT TO AT MOST 300 LINES. IF MORE CONTENT NEEDS TO be ADDED USE THE str-replace-editor TOOL TO EDIT THE FILE AFTER IT HAS BEEN CREATED.", "path": "pm2-manager.sh", "file_content": "#!/bin/bash\n\n# PM2 \u7ba1\u7406\u811a\u672c - \u667a\u653f\u5927\u6a21\u578b\u5f00\u53d1\u6846\u67b6\n# \u7528\u4e8e\u7ba1\u7406\u524d\u7aef\u548c\u540e\u7aef\u670d\u52a1\u7684\u542f\u52a8\u3001\u505c\u6b62\u3001\u91cd\u542f\u7b49\u64cd\u4f5c\n\n# \u989c\u8272\u5b9a\u4e49\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# \u65e5\u5fd7\u51fd\u6570\nlog_info() {\n echo -e \"${GREEN}[INFO]${NC} $1\"\n}\n\nlog_warn() {\n echo -e \"${YELLOW}[WARN]${NC} $1\"\n}\n\nlog_error() {\n echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nlog_blue() {\n echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\n# \u68c0\u67e5PM2\u662f\u5426\u5b89\u88c5\ncheck_pm2() {\n if ! command -v pm2 &> /dev/null; then\n log_error \"PM2 \u672a\u5b89\u88c5\uff0c\u8bf7\u5148\u5b89\u88c5 PM2: npm install -g pm2\"\n exit 1\n fi\n}\n\n# \u521b\u5efa\u65e5\u5fd7\u76ee\u5f55\ncreate_log_dirs() {\n mkdir -p logs\n mkdir -p server/logs\n log_info \"\u65e5\u5fd7\u76ee\u5f55\u5df2\u521b\u5efa\"\n}\n\n# \u6784\u5efa\u670d\u52a1\u7aef\u4ee3\u7801\nbuild_server() {\n log_info \"\u6784\u5efa\u670d\u52a1\u7aef\u4ee3\u7801...\"\n cd server\n if npm run build; then\n log_info \"\u670d\u52a1\u7aef\u6784\u5efa\u6210\u529f\"\n cd ..\n else\n log_error \"\u670d\u52a1\u7aef\u6784\u5efa\u5931\u8d25\"\n cd ..\n exit 1\n fi\n}\n\n# \u542f\u52a8\u6240\u6709\u670d\u52a1\nstart_all() {\n log_info \"\u542f\u52a8\u6240\u6709\u670d\u52a1...\"\n create_log_dirs\n build_server\n pm2 start ecosystem.config.js\n log_info \"\u6240\u6709\u670d\u52a1\u5df2\u542f\u52a8\"\n show_status\n}\n\n# \u542f\u52a8\u5f00\u53d1\u73af\u5883\nstart_dev() {\n log_info \"\u542f\u52a8\u5f00\u53d1\u73af\u5883...\"\n create_log_dirs\n pm2 start ecosystem.config.js --env development\n log_info \"\u5f00\u53d1\u73af\u5883\u5df2\u542f\u52a8\"\n show_status\n}\n\n# \u542f\u52a8\u751f\u4ea7\u73af\u5883\nstart_prod() {\n log_info \"\u542f\u52a8\u751f\u4ea7\u73af\u5883...\"\n create_log_dirs\n build_server\n pm2 start ecosystem.config.js --env production\n log_info \"\u751f\u4ea7\u73af\u5883\u5df2\u542f\u52a8\"\n show_status\n}\n\n# \u505c\u6b62\u6240\u6709\u670d\u52a1\nstop_all() {\n log_info \"\u505c\u6b62\u6240\u6709\u670d\u52a1...\"\n pm2 stop ecosystem.config.js\n log_info \"\u6240\u6709\u670d\u52a1\u5df2\u505c\u6b62\"\n}\n\n# \u91cd\u542f\u6240\u6709\u670d\u52a1\nrestart_all() {\n log_info \"\u91cd\u542f\u6240\u6709\u670d\u52a1...\"\n pm2 restart ecosystem.config.js\n log_info \"\u6240\u6709\u670d\u52a1\u5df2\u91cd\u542f\"\n show_status\n}\n\n# \u5220\u9664\u6240\u6709\u670d\u52a1\ndelete_all() {\n log_warn \"\u5220\u9664\u6240\u6709PM2\u670d\u52a1...\"\n pm2 delete ecosystem.config.js\n log_info \"\u6240\u6709\u670d\u52a1\u5df2\u5220\u9664\"\n}\n\n# \u663e\u793a\u670d\u52a1\u72b6\u6001\nshow_status() {\n log_blue \"\u670d\u52a1\u72b6\u6001\uff1a\"\n pm2 status\n}\n\n# \u663e\u793a\u65e5\u5fd7\nshow_logs() {\n if [ -z \"$2\" ]; then\n log_blue \"\u663e\u793a\u6240\u6709\u670d\u52a1\u65e5\u5fd7\uff1a\"\n pm2 logs\n else\n log_blue \"\u663e\u793a $2 \u670d\u52a1\u65e5\u5fd7\uff1a\"\n pm2 logs \"$2\"\n fi\n}\n\n# \u76d1\u63a7\u670d\u52a1\nmonitor() {\n log_blue \"\u542f\u52a8PM2\u76d1\u63a7\u754c\u9762...\"\n pm2 monit\n}\n\n# \u91cd\u8f7d\u670d\u52a1\uff08\u96f6\u505c\u673a\u91cd\u542f\uff09\nreload_all() {\n log_info \"\u91cd\u8f7d\u6240\u6709\u670d\u52a1\uff08\u96f6\u505c\u673a\u91cd\u542f\uff09...\"\n pm2 reload ecosystem.config.js\n log_info \"\u6240\u6709\u670d\u52a1\u5df2\u91cd\u8f7d\"\n show_status\n}\n\n# \u663e\u793a\u5e2e\u52a9\u4fe1\u606f\nshow_help() {\n echo -e \"${BLUE}PM2 \u7ba1\u7406\u811a\u672c\u4f7f\u7528\u8bf4\u660e${NC}\"\n echo \"\"\n echo \"\u7528\u6cd5: ./pm2-manager.sh [\u547d\u4ee4]\"\n echo \"\"\n echo \"\u53ef\u7528\u547d\u4ee4:\"\n echo \" start \u542f\u52a8\u6240\u6709\u670d\u52a1\"\n echo \" start:dev \u542f\u52a8\u5f00\u53d1\u73af\u5883\"\n echo \" start:prod \u542f\u52a8\u751f\u4ea7\u73af\u5883\"\n echo \" stop \u505c\u6b62\u6240\u6709\u670d\u52a1\"\n echo \" restart \u91cd\u542f\u6240\u6709\u670d\u52a1\"\n echo \" reload \u91cd\u8f7d\u6240\u6709\u670d\u52a1\uff08\u96f6\u505c\u673a\u91cd\u542f\uff09\"\n echo \" delete \u5220\u9664\u6240\u6709\u670d\u52a1\"\n echo \" status \u663e\u793a\u670d\u52a1\u72b6\u6001\"\n echo \" logs [name] \u663e\u793a\u65e5\u5fd7\uff08\u53ef\u9009\u6307\u5b9a\u670d\u52a1\u540d\uff09\"\n echo \" monitor \u542f\u52a8\u76d1\u63a7\u754c\u9762\"\n echo \" help \u663e\u793a\u6b64\u5e2e\u52a9\u4fe1\u606f\"\n echo \"\"\n echo \"\u670d\u52a1\u540d\u79f0:\"\n echo \" vector-web-frontend \u524d\u7aef\u670d\u52a1\"\n echo \" vector-web-server \u540e\u7aef\u670d\u52a1\"\n echo \"\"\n}\n\n# \u4e3b\u51fd\u6570\nmain() {\n check_pm2\n \n case \"$1\" in\n \"start\")\n start_all\n ;;\n \"start:dev\")\n start_dev\n ;;\n \"start:prod\")\n start_prod\n ;;\n \"stop\")\n stop_all\n ;;\n \"restart\")\n restart_all\n ;;\n \"reload\")\n reload_all\n ;;\n \"delete\")\n delete_all\n ;;\n \"status\")\n show_status\n ;;\n \"logs\")\n show_logs \"$@\"\n ;;\n \"monitor\")\n monitor\n ;;\n \"help\"|\"--help\"|\"-h\")\n show_help\n ;;\n \"\")\n log_warn \"\u8bf7\u6307\u5b9a\u547d\u4ee4\uff0c\u4f7f\u7528 './pm2-manager.sh help' \u67e5\u770b\u5e2e\u52a9\"\n ;;\n *)\n log_error \"\u672a\u77e5\u547d\u4ee4: $1\"\n log_info \"\u4f7f\u7528 './pm2-manager.sh help' \u67e5\u770b\u53ef\u7528\u547d\u4ee4\"\n exit 1\n ;;\n esac\n}\n\n# \u6267\u884c\u4e3b\u51fd\u6570\nmain \"$@\""}","mcp_server_name":"","mcp_tool_name":""}},{"id":2,"ty