 1	import express from 'express';
 2	import cors from 'cors';
 3	import helmet from 'helmet';
 4	import compression from 'compression';
 5	import path from 'path';
 6	import { logger } from './utils/logger';
 7	
 8	// 导入中间件
 9	import { apiKeyAuth, userAuth } from './middleware/auth';
 10	import { errorHandler, notFoundHandler, ApiError } from './middleware/errorHandler';
 11	import { rateLimit } from './middleware/rateLimit';
 12	import { cacheMiddleware } from './middleware/cache';
 13	
 14	// 环境变量配置
 15	import dotenv from 'dotenv';
 16	dotenv.config({ path: path.resolve(__dirname, '../.env') });
 17	
 18	// 导入API路由
 19	import knowledgeRoutes from './api/knowledge';
 20	import vectorRoutes from './api/vector';
 21	import modelRoutes from './api/model';
 22	import qaRoutes from './api/qa';
 23	import authRoutes from './api/auth';
 24	import assistantRoutes from './api/assistants';
 25	
 26	const app = express();
 27	const PORT = process.env.PORT || 3001;
 28	const isDev = process.env.NODE_ENV !== 'production';
 29	
 30	// 基础中间件配置
 31	app.use(helmet());
 32	app.use(cors({
 33	 origin: process.env.CORS_ORIGIN || '*',
 34	 methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
 35	 allowedHeaders: ['Content-Type', 'Authorization', 'x-api-key']
 36	}));
 37	app.use(compression());
 38	app.use(express.json({ limit: '10mb' }));
 39	app.use(express.urlencoded({ extended: true, limit: '10mb' }));
 40	
 41	// 请求日志
 42	app.use((req, res, next) => {
 43	 logger.info(`${req.method} ${req.originalUrl} ${req.ip}`);
 44	 next();
 45	});
 46	
 47	// 速率限制 - 全局限制 (每分钟100个请求)
 48	app.use(rateLimit({
 49	 windowMs: 60 * 1000,
 50	 max: isDev ? 0 : 100, // 开发环境禁用限制
 51	 message: '请求过于频繁，请稍后再试'
 52	}));
 53	
 54	// API认证
 55	app.use('/api', apiKeyAuth);
 56	
 57	// 路由定义
 58	// 健康检查端点 (无需认证)
 59	app.get('/health', (req, res) => {
 60	 res.status(200).json({ 
 61	 status: 'ok',
 62	 timestamp: new Date().toISOString(),
 63	 version: process.env.npm_package_version || '0.1.0',
 64	 environment: process.env.NODE_ENV || 'development'
 65	 });
 66	});
 67	
 68	// API路由 (使用缓存中间件)
 69	app.use('/api/auth', authRoutes); // 认证接口不使用缓存
 70	app.use('/api/assistants', cacheMiddleware({ ttl: 5 * 60 * 1000 }), assistantRoutes);
 71	app.use('/api/knowledge', cacheMiddleware({ ttl: 5 * 60 * 1000 }), knowledgeRoutes);
 72	app.use('/api/vector', cacheMiddleware({ ttl: 5 * 60 * 1000 }), vectorRoutes);
 73	app.use('/api/model', cacheMiddleware({ ttl: 10 * 60 * 1000 }), modelRoutes);
 74	app.use('/api/qa', cacheMiddleware({ ttl: 2 * 60 * 1000 }), qaRoutes);
 75	
 76	// 404处理 - 必须在所有路由之后
 77	app.use(notFoundHandler);
 78	
 79	// 错误处理中间件 - 必须在最后
 80	app.use(errorHandler);
 81	
 82	// 未捕获的异常处理
 83	process.on('uncaughtException', (error) => {
 84	 logger.error('未捕获的异常:', error);
 85	 if (process.env.NODE_ENV === 'production') {
 86	 // 在生产环境中，优雅地关闭应用
 87	 process.exit(1);
 88	 }
 89	});
 90	
 91	process.on('unhandledRejection', (reason) => {
 92	 logger.error('未处理的Promise拒绝:', reason);
 93	});
 94	
 95	// 启动服务器
 96	if (require.main === module) {
 97	 const server = app.listen(PORT, () => {
 98	 logger.info(`服务运行在 http://localhost:${PORT}, 环境: ${process.env.NODE_ENV || 'development'}`);
 99	 });
 100	
 101	 // 优雅关闭
 102	 const shutdown = () => {
 103	 logger.info('接收到关闭信号，优雅关闭中...');
 104	 server.close(() => {
 105	 logger.info('HTTP服务器已关闭');
 106	 process.exit(0);
 107	 });
 108	 
 109	 // 如果10秒内没有关闭，则强制退出
 110	 setTimeout(() => {
 111	 logger.error('强制关闭 - 无法在时间限制内完成优雅关闭');
 112	 process.exit(1);
 113	 }, 10000);
 114	 };
 115	
 116	 // 监听终止信号
 117	 process.on('SIGTERM', shutdown);
 118	 process.on('SIGINT', shutdown);
 119	}
 120	
 121	export default app;
